#include <cstdint>

/** \addtogroup Core
 * \{ */
/** \addtogroup System_Parameters
 * \{ */


// carrier and code frequencies
constexpr double GPS_L1C_FREQ_HZ = FREQ1;                  //!< GPS L1C carrier frequency [Hz]
constexpr double GPS_L1C_CODE_CHIP_RATE_CPS = 1.023e6;     //!< GPS L1C code rate [chips/s]
constexpr double GPS_L1C_CODE_PERIOD_S = 0.010;            //!< GPS L1C code period [s]
constexpr int GPS_L1C_CODE_PERIOD_MS = 10;                 //!< GPS L1C code period [ms]
constexpr double GPS_L1C_CODE_LENGTH_CHIPS = 10230.0;      //!< GPS L1C code length [chips]
constexpr double GPS_L1C_SUB_CARRIER_P_RATE_HZ = 1.023e6;  //!< GPS L1C sub-carrier 'p' rate [Hz]
constexpr double GPS_L1C_SUB_CARRIER_D_RATE_HZ = 6.138e6;  //!< GPS L1C sub-carrier 'd' rate [Hz]
constexpr double GPS_L1C_D_SYMBOL_RATE_BPS = 100.0;        //!< GPS L1C navdata symbol rate [bits/second]
constexpr double GPS_L1C_O_CODE_PERIOD_S = 18.0;           //!< GPS L1C overlay code period [s]
constexpr double GPS_L1C_O_CODE_CHIP_RATE_BPS = 100.0;     //!< GPS L1C overlay code rate [chips/s]
constexpr double GPS_L1C_O_CODE_LENGTH_CHIPS = 1800.0;     //!< GPS L1C overlay code length [chips]


// navdata
constexpr int GPS_L1C_TOI_BCH_BITS = 52;         //!< Number of bits of TOI when BCH encoded (as received in SIS)
constexpr int GPS_L1C_TOI_BITS = 9;              //!< Number of bits of TOI when decoded
constexpr int GPS_L1C_FRAME_BITS = 1800;         //!< Number of bits in a complete frame
constexpr int GPS_L1C_SF_2_ENCODED_BITS = 1200;  //!< Number of bits in a LDPC encoded subframe 2
constexpr int GPS_L1C_SF_3_ENCODED_BITS = 548;   //!< Number of bits in a LDPC encoded subframe 3
constexpr int GPS_L1C_SF_2_DATA_BITS = 600;      //!< Number of bits in a decoded subframe 2
constexpr int GPS_L1C_SF_3_DATA_BITS = 274;      //!< Number of bits in a decoded subframe 3
constexpr int GPS_L1C_TOI_LSB_VALUES = 256;      //!< Number of possible LSB for TOI

constexpr int GPS_L1C_SF_2_DATA_BYTES = 75;  //!< Number of bytes in a decoded subframe 2
constexpr int GPS_L1C_SF_3_DATA_BYTES = 35;  //!< Number of bytes in a decoded subframe 3, the last byte has 6 bits of zero-padding

constexpr int GPS_L1C_SF_2_AND_3_ENCODED_BITS = GPS_L1C_SF_2_ENCODED_BITS + GPS_L1C_SF_3_ENCODED_BITS;

constexpr int GPS_L1C_CRC_POLYNOMIAL = 0x1864CFB;

constexpr int GPS_L1C_INTERLEAVE_ROWS = 38;  //!< Number of rows in the interlaver block
constexpr int GPS_L1C_INTERLEAVE_COLS = 46;  //!< Number of columns in the interlaver block

// TODO: Check if this value is sensible
constexpr uint32_t GPS_L1C_OPT_ACQ_FS_SPS = 2000000;  //!< Sampling frequency that maximizes the acquisition SNR while using a non-multiple of chip rate

